def get_shapes(grid, shape_id):
    """Extract all shapes of a given color from grid, returning their bounding boxes and pixel locations."""
    shapes = []
    h, w = len(grid), len(grid[0])
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == shape_id and (r, c) not in seen:
                # BFS to find the connected shape
                shape_pixels = []
                queue = [(r, c)]
                seen.add((r, c))

                while queue:
                    cr, cc = queue.pop(0)
                    shape_pixels.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == shape_id and (nr, nc) not in seen:
                            seen.add((nr, nc))
                            queue.append((nr, nc))

                # Get bounding box
                rows = [pr[0] for pr in shape_pixels]
                cols = [pr[1] for pr in shape_pixels]
                min_row, max_row = min(rows), max(rows)
                min_col, max_col = min(cols), max(cols)

                shapes.append({
                    'id': shape_id,
                    'pixels': shape_pixels,
                    'bbox': (min_row, min_col, max_row, max_col),
                    'h': max_row - min_row + 1,
                    'w': max_col - min_col + 1
                })

    return shapes

def extract_all_shapes(grid):
    """Extract all shapes with their positions."""
    found_colors = set()
    shapes = {}
    for color in set(color for row in grid for color in row if color != 0):
        found_colors.add(color)
        shapes[color] = get_shapes(grid, color)
    return shapes

