def get_isolated_cells(grid):
    """Find single isolated pixels (no same-color neighbors with 8-connectivity)."""
    isolated = set()
    checked = set()
    h, w = len(grid), len(grid[0])

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r, c) in checked:
                continue

            color = grid[r][c]
            has_neighbor = False
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                        has_neighbor = True
                        break
                if has_neighbor:
                    break

            if not has_neighbor:
                isolated.add((r, c))

            # Mark all reachable same-color cells as checked
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr, nc) in isolated:
                        pass  # This is isolated, should continue with its own check
                    elif 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                        break  # has neighbor, stop this color's processing

    return isolated

