    shapes_by_color = {}
    found_single = set()

    h, w = len(grid), len(grid[0])

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                continue
            if (r, c) in found_single:
                continue

            color = grid[r][c]
            bbox_origin = (r, c)

            # BFS to find connected pixels
            pixels = []
            queue = [(r, c)]
            found_single.add((r, c))

            while queue:
                cr, cc = queue.pop(0)
                pixels.append((cr, cc))
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = cr + dr, cc + dc
                        if (nr, nc) not in found_single and 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                            found_single.add((nr, nc))
                            queue.append((nr, nc))

            if len(pixels) > 1:
                rows = [pr[0] for pr in pixels]
                cols = [pr[1] for pr in pixels]
                min_r, max_r = min(rows), max(rows)
                min_c, max_c = min(cols), max(cols)

                # Convert to relative coordinates
                relative_pixels = [(pr - min_r, pc - min_c) for pr, pc in pixels]

